/* LexHukuk — dependency-free, GitHub Pages-friendly frontend. */
(() => {
'use strict';
const db = window.LEXHUKUK_DATA || {terms:[],categories:[],lists:[]};
const STORAGE = 'lexhukuk-pages-v1';
const defaultState = {favorites:[], progress:{}, myLists:[], custom:[], hidden:[], dailyGoal:20, sessions:[], reports:[]};
let state;
try { state = {...defaultState, ...JSON.parse(localStorage.getItem(STORAGE)||'{}')}; } catch { state={...defaultState}; }
for(const k of ['favorites','myLists','custom','hidden','sessions','reports']) if(!Array.isArray(state[k]))state[k]=[];
if(!state.progress || typeof state.progress!=='object') state.progress={};
const icon = (name,cls='') => `<svg class="ico ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const E = x => String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = E;
const norm=x=>String(x??'').toLocaleLowerCase('tr-TR').replace(/ß/g,'ss').replace(/ä/g,'a').replace(/ö/g,'o').replace(/ü/g,'u').replace(/ı/g,'i').replace(/[^a-z0-9ğüşöçıİ\s-]/gi,'').trim();
const unique=xs=>[...new Set(xs)];
const shuffle=xs=>{const arr=[...xs];for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}return arr;};
const today=()=>new Date().toISOString().slice(0,10);
const daysFromNow=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);};
const persist=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('Tarayıcı depolama alanı dolu. Verileri dışa aktarmayı deneyin.');}};
const allTerms=()=>{const extras=new Map((state.custom||[]).map(x=>[x.id,x]));return [...db.terms,...state.custom.filter(x=>!db.terms.some(t=>t.id===x.id))].filter(t=>!state.hidden.includes(t.id)).map(t=>extras.get(t.id)||t);};
const getTerm=id=>allTerms().find(t=>t.id===id);
const cat=id=>db.categories.find(c=>c.id===id)||{tr:'Diğer',de:'Sonstige',description:''};
const lists=()=>[...db.lists,...state.myLists.map(l=>({...l,kind:'personal',category:'personal',subtitle:'Benim listem',description:'Kişisel çalışma koleksiyonu',level:'Karma'}))];
const getList=id=>lists().find(l=>l.id===id);
const listTerms=id=>{const l=getList(id);return l?l.ids.map(getTerm).filter(Boolean):allTerms();};
const fmtTerm=t=>t.de;
let dictionary={query:'',category:'all',level:'all',sort:'az',type:'all'};
let listFilter={query:'',kind:'all'};
let session=null;
let noticeTimer;
let mobileOpen=false;
function toast(message){const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function header(active){
const nav=[['home','Ana Sayfa','#/'],['dictionary','Sözlük','#/dictionary'],['lists','Kelime Listeleri','#/lists'],['study','Çalışma Alanı','#/study'],['dashboard','Panelim','#/dashboard'],['about','Hakkında','#/about']];
return `<a class="skip" href="#main">İçeriğe geç</a><header class="site-header"><div class="header-in"><a href="#/" class="brand" aria-label="LexHukuk ana sayfa"><span class="brand-logo">L</span><span class="brand-title">Lex<em>Hukuk</em></span></a><nav class="nav ${mobileOpen?'open':''}" aria-label="Ana menü">${nav.map(([id,label,url])=>`<a class="${active===id?'active':''}" href="${url}">${label}</a>`).join('')}</nav><div class="header-actions"><a class="btn btn-primary" href="#/study">${icon('card')} Çalışmaya Başla</a><button type="button" class="icon-btn mobile-menu" data-action="menu" aria-label="Menüyü aç veya kapat">${icon('menu')}</button></div></div></header>`;
}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-in"><div><a class="brand" href="#/"><span class="brand-logo">L</span><span class="brand-title">Lex<em>Hukuk</em></span></a><p class="tiny" style="margin:12px 0 0;max-width:340px">Hukuk dilini anlaşılır, öğrenmeyi erişilebilir kılmak için hazırlanmış bir eğitim sözlüğü.</p></div><nav aria-label="Alt menü"><a href="#/dictionary">Sözlük</a><a href="#/lists">Kelime Listeleri</a><a href="#/study">Çalışma</a><a href="#/about">Hakkında</a><a href="#/editor">Yerel Editör</a></nav></div><div class="fineprint">© ${new Date().getFullYear()} LexHukuk · Eğitim amaçlı prototip. Hukuki danışmanlık değildir. Veriler bu cihazın tarayıcısında tutulur.</div></div></footer>`;}
function wrap(body,active='home'){return header(active)+`<main id="main" class="main-shell">${body}</main>`+footer();}
function heading(title,description='',crumbs=[]){return `<section class="page-heading"><div class="container">${crumbs.length?`<div class="crumbs"><a href="#/">Ana Sayfa</a> ${crumbs.map((c,i)=>`<span>/</span>${c.url?`<a href="${c.url}">${E(c.label)}</a>`:`<span>${E(c.label)}</span>`}`).join('')}</div>`:''}<span class="kicker">LEXHUKUK AKADEMİ</span><h1>${E(title)}</h1><p>${E(description)}</p></div></section>`;}
function preview(t){return `<div class="surface card card-hover word-mini"><div><h4><a href="#/word/${encodeURIComponent(t.id)}">${E(t.de)}</a></h4><p>${E(t.tr)}</p><div class="muted">${E(cat(t.category).tr)} · ${E(t.level)}</div></div><button class="icon-btn ${state.favorites.includes(t.id)?'on':''}" data-action="favorite" data-id="${attr(t.id)}" aria-label="Favorilere ekle veya çıkar">${icon('heart')}</button></div>`;}
function searchBox(id,placeholder='',cls=''){return `<div class="search-wrap ${cls}"><form class="search-box" data-form="search"><span class="searchicon">${icon('search','lg')}</span><input autocomplete="off" id="${id}" name="query" data-search="true" placeholder="${attr(placeholder||'Bir terim arayın: Anspruch, Urteil, Vertrag…')}" aria-label="Sözlük araması"><button class="btn btn-primary" type="submit">Ara ${icon('arrow')}</button></form><div class="suggestions" id="${id}-suggestions" hidden></div></div>`;}
function home(){
const terms=allTerms();const dayTerm=terms[Math.floor((Date.now()/86400000)%terms.length)]||db.terms[0];
const special=['Vertrag','Anspruch','Klage','Urteil','Haftung','Eigentum'];
const featured=lists().filter(l=>l.kind==='featured').slice(0,3);
const cats=db.categories.filter(c=>c.id!=='general').slice(0,8);
return `<div class="hero"><div class="container"><div class="hero-grid"><div><div class="eyebrow">ALMANCA–TÜRKÇE HUKUK SÖZLÜĞÜ</div><h1>Hukukun Dili,<br><span>Bilginin Anahtarı.</span></h1><p class="lead">Almanca hukuk terminolojisini Türkçe karşılıkları, bağlamlı örnek cümleleri ve interaktif çalışma araçlarıyla keşfedin.</p>${searchBox('heroSearch')}<div class="tags"><span class="tiny muted">Popüler:</span>${special.map(s=>`<button type="button" class="tag" data-action="search-word" data-value="${attr(s)}">${E(s)}</button>`).join('')}</div><div class="stats-strip"><div><strong>${terms.filter(t=>t.legal).length}+</strong><span>Hukuki terim</span></div><div><strong>17</strong><span>Hukuk alanı</span></div><div><strong>4</strong><span>Çalışma modu</span></div></div></div><div class="hero-card"><div class="kicker">${icon('spark')} GÜNÜN HUKUK TERİMİ</div><h3>${E(dayTerm.de)}</h3><div class="definition">${E(dayTerm.tr)}</div><p class="example">“${E(dayTerm.examples[0].de)}”</p><div class="translate">${E(dayTerm.examples[0].tr)}</div><div class="foot"><span class="pill">${E(cat(dayTerm.category).tr)}</span><a class="btn btn-gold small" href="#/word/${encodeURIComponent(dayTerm.id)}">Kelimeyi incele ${icon('arrow')}</a></div></div></div></div></div>
<section class="section"><div class="container"><div class="section-top"><div><div class="kicker">ÖĞRENME KOLEKSİYONLARI</div><h2>Popüler kelime listeleri</h2><p>Hukuk alanlarına göre hazırlanmış kelime listelerini keşfedin ve hemen çalışmaya başlayın.</p></div><a href="#/lists" class="link">Tüm listeler ${icon('arrow','sm')}</a></div><div class="grid three">${featured.map(listCard).join('')}</div></div></section>
<section class="section" style="background:#f7f3e9"><div class="container"><div class="section-top"><div><div class="kicker">KATEGORİLER</div><h2>Hukuk alanlarına göre keşfet</h2><p>Alman hukukunun temel disiplinlerini ayrıntılı kelime listeleriyle öğrenin.</p></div><a href="#/lists" class="link">17 alanın tümü ${icon('arrow','sm')}</a></div><div class="grid four">${cats.map(categoryCard).join('')}</div></div></section>
<section class="section"><div class="container"><div class="section-top"><div><div class="kicker">ÖĞRENME ARAÇLARI</div><h2>Okumakla kalmayın, hatırlayın.</h2><p>Kelimeleri kalıcı öğrenmek için dört etkileşimli yöntem.</p></div></div><div class="grid four">${[['card','Kelime Kartları','İki yönlü kartlarla hatırlama çalışın.','flash'],['check','Çoktan Seçmeli','Dört seçenekten doğru anlamı bulun.','quiz'],['edit','Yazma Alıştırması','Almanca terimleri kendi kendinize yazın.','write'],['grid','Eşleştirme','Terimleri ve karşılıklarını eşleştirin.','match']].map(([ic,title,desc,mode])=>`<a href="#/study" class="surface card card-hover"><div class="category-icon">${icon(ic,'lg')}</div><h3 style="margin:19px 0 7px">${title}</h3><p class="muted tiny">${desc}</p><span class="link">Çalışmaya başla ${icon('arrow','sm')}</span></a>`).join('')}</div></div></section>
<section class="cta-section"><div class="container cta-flex"><div><span class="kicker">HER GÜN BİRAZ DAHA İLERİ</span><h2>Hukuk Almancasında ustalaşın.</h2><p>Kelime listelerini seçin, kartları çevirin, ilerlemenizi izleyin.</p></div><a href="#/study" class="btn btn-gold">Çalışma alanına git ${icon('arrow')}</a></div></section>`;
}
function categoryCard(c){const n=allTerms().filter(t=>t.category===c.id).length;return `<a class="surface category-card card-hover" href="#/list/cat-${attr(c.id)}"><span class="category-icon">§</span><span><span class="cat-title">${E(c.tr)}</span><span class="cat-desc">${E(c.de)}</span><small>${n} KELİME</small></span></a>`;}
function listCard(l){return `<a class="surface card list-card card-hover" href="#/list/${attr(l.id)}"><span class="list-icon">${icon('book','lg')}</span><h3>${E(l.name)}</h3><p>${E(l.subtitle)}</p><div class="list-meta"><span class="pill blue">${E(l.level||'Karma')}</span><span>${l.ids.filter(id=>getTerm(id)).length} kelime ${icon('arrow','sm')}</span></div></a>`;}
function levenshtein(a,b){if(Math.abs(a.length-b.length)>3)return 9;let dp=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let last=dp[0];dp[0]=i;for(let j=1;j<=b.length;j++){const prev=dp[j];dp[j]=Math.min(dp[j]+1,dp[j-1]+1,last+(a[i-1]===b[j-1]?0:1));last=prev;}}return dp[b.length];}
function searchResults(q,items=allTerms()){const query=norm(q);if(!query)return [...items];let matches=items.map(t=>{const primary=norm(t.de.replace(/^(der|die|das)\s/,'')),full=norm(t.de),tr=norm(t.tr);const score=(primary===query||full===query)?0:(primary.startsWith(query)||tr.startsWith(query))?1:(primary.includes(query)||tr.includes(query))?2:(norm(t.definitionTR).includes(query)||norm(t.definitionDE).includes(query))?3:10;return {t,score};}).filter(o=>o.score<10).sort((a,b)=>a.score-b.score||a.t.de.localeCompare(b.t.de,'de')).map(o=>o.t);
if(matches.length)return matches;
return items.filter(t=>levenshtein(norm(t.word),query)<=Math.max(1,Math.min(2,Math.round(query.length/5)))).slice(0,7);
}
function dictionaryView(){const p = new URLSearchParams((location.hash.split('?')[1]||''));if(p.has('q'))dictionary.query=p.get('q')||'';
let terms=searchResults(dictionary.query);
if(dictionary.category!=='all')terms=terms.filter(t=>t.category===dictionary.category);
if(dictionary.level!=='all')terms=terms.filter(t=>t.level===dictionary.level);
if(dictionary.type!=='all')terms=terms.filter(t=>t.type===dictionary.type);
terms.sort((a,b)=>dictionary.sort==='za'?b.de.localeCompare(a.de,'de'):a.de.localeCompare(b.de,'de'));
const select=(key,opts)=>`<select data-filter="${key}" class="field" aria-label="${key} filtresi">${opts.map(([value,name])=>`<option value="${attr(value)}" ${dictionary[key]===value?'selected':''}>${E(name)}</option>`).join('')}</select>`;
return `${heading('Hukuk Terimleri Sözlüğü','Almanca ve Türkçe arasında arama yapın; kelimeleri açıklamaları ve örnek cümleleriyle keşfedin.',[{label:'Sözlük'}])}<div class="container page-content"><div class="toolbar"><div class="search-box"><span class="searchicon">${icon('search')}</span><input class="input" id="dictionaryInput" data-dictionary-query="true" value="${attr(dictionary.query)}" placeholder="Almanca veya Türkçe terim arayın…" aria-label="Sözlükte ara"></div>${select('category',[['all','Tüm hukuk alanları'],...db.categories.map(c=>[c.id,c.tr])])}${select('level',[['all','Tüm seviyeler'],...['A1','A2','B1','B2','C1'].map(x=>[x,x])])}${select('sort',[['az','A → Z'],['za','Z → A']])}</div><div class="results-info"><span><strong>${terms.length}</strong> sonuç ${dictionary.query?`· “${E(dictionary.query)}”`:''}</span><span>Terimler bağlamlara göre açıklanır.</span></div>${terms.length?`<div class="results-list">${terms.slice(0,100).map(resultRow).join('')}</div>`:`<div class="surface empty">${icon('search','lg')}<h3>Terim bulunamadı</h3><p>Yazımı veya filtreleri değiştirerek yeniden deneyin.</p><button class="btn btn-outline" data-action="reset-dictionary">Filtreleri temizle</button></div>`}</div>`;}
function resultRow(t){return `<div class="surface result"><div><div class="title-line"><h3><a href="#/word/${attr(t.id)}">${E(t.de)}</a></h3><span class="pill blue">${E(t.level)}</span></div><p class="tr">${E(t.tr)}</p><p class="desc">${E(t.definitionTR)} · ${E(cat(t.category).tr)}</p></div><div class="actions"><button data-action="sound" data-text="${attr(t.de)}" class="icon-btn" aria-label="Sesli dinle">${icon('sound')}</button><button data-action="favorite" data-id="${attr(t.id)}" class="icon-btn ${state.favorites.includes(t.id)?'on':''}" aria-label="Favorilere ekle">${icon('heart')}</button><a class="btn btn-light small" href="#/word/${attr(t.id)}">İncele ${icon('arrow','sm')}</a></div></div>`;}
function cases(t){if(!t.article)return '<p class="muted tiny">Bu kelime için isim çekim tablosu geçerli değil.</p>';
const a=t.article;const arts={der:['der','den','dem','des'],die:['die','die','der','der'],das:['das','das','dem','des']}[a]||[];
return `<table class="grammar-table"><thead><tr><th>Hâl</th><th>Belirli artikel</th></tr></thead><tbody>${['Nominativ','Akkusativ','Dativ','Genitiv'].map((x,i)=>`<tr><td>${x}</td><td>${arts[i]||'—'}</td></tr>`).join('')}</tbody></table><p class="muted tiny" style="margin-top:10px">Tablo artikeli gösterir; isim kökü ve bazı son ekler çekime göre değişebilir.</p>`;}
function wordView(id){const t=getTerm(id);if(!t)return missing();const related=allTerms().filter(v=>v.category===t.category&&v.id!==t.id).slice(0,7);
const favorite=state.favorites.includes(t.id);
return `${heading(t.de,t.tr,[{label:'Sözlük',url:'#/dictionary'},{label:t.de}])}<div class="container page-content"><div class="detail-layout"><div class="detail-main"><div class="surface detail-lead"><div class="row-flex"><span class="kicker">${t.legal?'HUKUK TERİMİ':'GENEL ALMANCA'}</span><span class="pill">${E(cat(t.category).de)}</span></div><div class="detail-word">${E(t.de)} <button class="icon-btn" data-action="sound" data-text="${attr(t.de)}" aria-label="Almanca telaffuzu dinle">${icon('sound')}</button></div><p class="detail-tr">${E(t.tr)}</p><div class="detail-actions"><button data-action="favorite" data-id="${attr(t.id)}" class="btn ${favorite?'btn-gold':'btn-outline'}">${icon('heart')} ${favorite?'Favorilerden Çıkar':'Favorilere Ekle'}</button><button class="btn btn-outline" data-action="pick-list" data-id="${attr(t.id)}">${icon('bookmark')} Listeme Ekle</button><button class="btn btn-outline" data-action="share" data-id="${attr(t.id)}">${icon('share')} Paylaş</button></div><div class="detail-definition"><h4>ALMANCA TANIM</h4><p lang="de">${E(t.definitionDE)}</p><h4>TÜRKÇE AÇIKLAMA</h4><p>${E(t.definitionTR)}</p></div></div><div class="surface example-card"><div class="row-flex"><h3>Örnek Cümleler</h3><span class="pill blue">DE ↔ TR</span></div>${(t.examples||[]).map((ex,i)=>`<div class="example-row"><div class="top"><div class="de" lang="de">${E(ex.de)}</div><button class="icon-btn" data-action="sound" data-text="${attr(ex.de)}" aria-label="${i+1}. cümleyi seslendir">${icon('sound')}</button></div><div class="tr">${E(ex.tr)}</div></div>`).join('')}</div><div class="surface card"><h3>İlişkili Terimler</h3><p class="muted tiny">Aynı hukuk alanındaki kavramları keşfedin.</p><div class="term-links">${related.map(r=>`<a class="tag" href="#/word/${attr(r.id)}">${E(r.de)} ${icon('arrow','sm')}</a>`).join('')}</div></div></div><aside class="detail-side"><div class="surface card"><h3>Kelime Bilgisi</h3><div class="meta-rows">${[['Artikel',t.article||'—'],['Sözcük türü',t.type],['Çoğul',t.plural||'Belirtilmemiş'],['Hukuk alanı',cat(t.category).tr],['Dil seviyesi',t.level],['Bağlam',t.legal?'Ağırlıkla Alman hukuku':'Genel dil']].map(([a,b])=>`<div class="meta-row"><span class="key">${E(a)}</span><span class="value">${E(b)}</span></div>`).join('')}</div></div><div class="surface card"><h3>İsimlerin Halleri</h3>${cases(t)}</div><div class="surface card"><h3>Bu kelimeyi çalışın</h3><p class="muted tiny">Kelimeyi birkaç saniyede aktif öğrenme moduna taşıyın.</p><button class="btn btn-primary" data-action="study-single" data-id="${attr(t.id)}">${icon('card')} Kartı çalış</button></div><div class="note">${icon('info')} Hukuki kavramların Almanya ve Türkiye'deki karşılıkları birebir örtüşmeyebilir. Bu sözlük öğrenme amaçlıdır.</div><button class="btn btn-light" data-action="report" data-id="${attr(t.id)}">Hatalı terimi bildir</button></aside></div></div>`;
}
function missing(){return `${heading('Sayfa bulunamadı','Aradığınız içerik artık mevcut değil.') }<div class="container page-content"><a href="#/" class="btn btn-primary">Ana sayfaya dön</a></div>`;}
function listsView(){const all=lists();const found=all.filter(l=>(listFilter.kind==='all'||(listFilter.kind==='law'&&l.kind==='category'&&l.category!=='general')||(listFilter.kind==='general'&&l.category==='general')||(listFilter.kind===l.kind))&&norm(l.name+' '+l.subtitle).includes(norm(listFilter.query)));
return `${heading('Kelime Listeleri','Hukuk alanları, seviyeler ve tematik başlıklar altında düzenlenen listelerle çalışın.',[{label:'Kelime Listeleri'}])}<div class="container page-content"><div class="toolbar"><div class="search-box"><span class="searchicon">${icon('search')}</span><input id="listSearch" value="${attr(listFilter.query)}" data-list-search="true" placeholder="Liste ara…" aria-label="Kelime listesi ara"></div></div><div class="tabs">${[['all','Tümü'],['law','Hukuk Alanları'],['general','Genel Almanca'],['featured','Tematik'],['personal','Listelerim']].map(([id,n])=>`<button class="tab ${listFilter.kind===id?'active':''}" data-action="list-filter" data-id="${id}">${n}</button>`).join('')}</div><div class="results-info">${found.length} kelime listesi</div>${found.length?`<div class="grid three">${found.map(listCard).join('')}</div>`:`<div class="surface empty">Bu aramayla eşleşen liste yok.</div>`}</div>`;}
function listView(id){const l=getList(id);if(!l)return missing();const terms=listTerms(l.id);
return `${heading(l.name,l.subtitle,[{label:'Kelime Listeleri',url:'#/lists'},{label:l.name}])}<div class="container page-content"><div class="surface card" style="margin-bottom:23px"><div class="list-detail-top"><div><span class="pill blue">${E(l.level||'Karma')}</span><h3 style="margin:12px 0 5px">${terms.length} kelimelik çalışma listesi</h3><p class="muted tiny">${E(l.description)}</p></div><div class="filterbar">${[['flash','Kartlar'],['quiz','Test'],['write','Yazma'],['match','Eşleştirme']].map(([mode,label])=>`<button class="btn ${mode==='flash'?'btn-primary':'btn-outline'}" data-action="start-study" data-list="${attr(l.id)}" data-mode="${mode}">${label} ${icon('arrow','sm')}</button>`).join('')}</div></div></div><div class="results-info"><span>ALMANCA KELİME LİSTESİ</span><span>${terms.length} kelime</span></div><div class="table-scroll"><table class="list-table"><thead><tr><th>ALMANCA</th><th>TÜRKÇE</th><th>TÜR</th><th>ÖRNEK CÜMLE</th><th>İŞLEMLER</th></tr></thead><tbody>${terms.map(t=>`<tr><td class="de"><a href="#/word/${attr(t.id)}">${E(t.de)}</a></td><td class="tr">${E(t.tr)}</td><td>${E(t.type)}</td><td class="muted">${E(t.examples[0]?.de||'—')}</td><td><button class="icon-btn ${state.favorites.includes(t.id)?'on':''}" data-action="favorite" data-id="${attr(t.id)}" aria-label="Favori">${icon('heart')}</button></td></tr>`).join('')}</tbody></table></div></div>`;}
function studyLanding(){const all=lists().filter(l=>l.ids.some(id=>getTerm(id)));const chosen=all.filter(l=>l.kind==='featured').slice(0,4);
return `${heading('Çalışma Alanı','Kelimeleri ezberlemek yerine anlayarak öğrenin; tekrar, test, yazma ve eşleştirme çalışın.',[{label:'Çalışma Alanı'}])}<div class="container page-content"><div class="section-top"><div><h2>Hangi yöntemle öğrenmek istersiniz?</h2><p>Önce bir kelime listesi seçin; sonra çalışma yöntemini belirleyin.</p></div></div><div class="grid four">${[['card','Kelime Kartları','Kartları çevirip bildiklerini işaretle.'],['check','Çoktan Seçmeli','Anlamı dört seçenek arasından bul.'],['edit','Yazma Alıştırması','Türkçe karşılığa bakıp Almancasını yaz.'],['grid','Eşleştirme','Kelime çiftlerini eşleştir.']].map(([ic,title,desc])=>`<div class="surface card"><div class="category-icon">${icon(ic,'lg')}</div><h3 style="margin:16px 0 8px">${title}</h3><p class="muted tiny">${desc}</p></div>`).join('')}</div><div class="section-top" style="margin-top:48px"><div><h2>Önerilen listeler</h2><p>Çalışmaya hemen başlamak için birini açın.</p></div><a href="#/lists" class="link">Tüm listeleri gör ${icon('arrow','sm')}</a></div><div class="grid three">${chosen.map(listCard).join('')}</div><div class="surface card" style="margin-top:22px"><div class="row-flex"><div><h3>Tüm sözlükten çalış</h3><p class="muted tiny">${allTerms().length} terim, karışık sırayla</p></div><div class="filterbar">${[['flash','Kartlar'],['quiz','Test'],['write','Yazma'],['match','Eşleştirme']].map(([m,n])=>`<button class="btn btn-outline" data-action="start-study" data-mode="${m}" data-list="all">${n}</button>`).join('')}</div></div></div></div>`;}
const modeNames={flash:'Kelime Kartları',quiz:'Çoktan Seçmeli Test',write:'Yazma Alıştırması',match:'Eşleştirme Oyunu'};
function makeSession(mode,listId,forcedIds){const terms=(forcedIds?forcedIds.map(getTerm).filter(Boolean):listId==='all'?allTerms():listTerms(listId));if(terms.length===0){toast('Bu listede henüz kelime bulunmuyor.');return;}const arr=shuffle(terms).map(t=>t.id);session={mode,listId,ids:mode==='quiz'||mode==='write'?arr.slice(0,Math.min(10,arr.length)):arr,idx:0,flipped:false,hint:false,reverse:false,selected:null,answers:[],written:false,matched:[],selectedLeft:null,selectedRight:null,wrongClicks:0,start:Date.now(),done:false};if(mode==='match')setupMatches();location.hash=`#/play/${mode}/${encodeURIComponent(listId)}`;render();}
function setupMatches(){const ids=session.ids.slice(0,6);session.matchIds=ids;session.left=shuffle(ids);session.right=shuffle(ids);session.matched=[];session.selectedLeft=null;session.selectedRight=null;}
function restoreSession(mode,listId){if(session&&session.mode===mode&&session.listId===listId)return;makeSession(mode,listId);}
function studyShell(title,body){const name=getList(session.listId)?.name||(session.listId==='single'?'Tek Kelime':'Tüm Sözlük');return `<div class="study-screen"><div class="study-shell"><div class="study-header"><div><a class="link tiny" href="#/study">${icon('left','sm')} Çalışma Alanı</a><h2>${title}</h2><p class="muted tiny">${E(name)} · ${session.ids.length} kelime</p></div><button class="btn btn-outline small" data-action="restart">${icon('refresh')} Yeniden Başla</button></div>${body}</div></div>`;}
function markProgress(id,learned){const prev=state.progress[id]||{box:0,count:0};let box=learned?Math.min(5,(prev.box||0)+1):0;const intervals=[0,1,3,7,14,30];state.progress[id]={box,count:(prev.count||0)+1,status:learned?(box>=3?'learned':'learning'):'review',last:today(),next:daysFromNow(intervals[box]||0)};persist();}
function saveSession(mode,correct,total){state.sessions.unshift({date:today(),mode,correct,total});state.sessions=state.sessions.slice(0,60);persist();}
function progressBar(){return `<div class="progress-track" aria-label="İlerleme"><div style="width:${Math.min(100,Math.round((session.idx+1)/session.ids.length*100))}%"></div></div>`;}
function flashView(){const t=getTerm(session.ids[session.idx]);if(!t)return missing();const q=session.reverse?t.tr:t.de;const a=session.reverse?t.de:t.tr;
return studyShell('Kelime Kartları',`<div class="row-flex" style="margin-top:17px"><span class="muted tiny">Kart ${session.idx+1} / ${session.ids.length}</span><button class="btn btn-light small" data-action="direction">${icon('refresh')} ${session.reverse?'TR → DE':'DE → TR'}</button></div>${progressBar()}<button class="flashcard ${session.flipped?'flipped':''}" data-action="flip" aria-label="Kartı çevir"><span class="front-label">${session.flipped?'CEVAP':'HATIRLAMAYA ÇALIŞ'}</span><div><h2>${E(session.flipped?a:q)}</h2><div class="translation">${session.flipped?E(t.examples[0]?.de||''):'Kartı çevirmek için dokunun'}</div></div><span class="${session.flipped?'answer-example':'hint'}">${session.flipped?E(t.examples[0]?.tr||''):(session.hint?`İpucu: ${E(cat(t.category).tr)} · ${E(t.article||t.word.slice(0,1))}`:'Boşluk tuşuyla da çevirebilirsiniz')}</span></button><div class="study-controls"><button class="btn btn-outline small" data-action="previous" ${session.idx===0?'disabled':''}>${icon('left')} Önceki</button><button class="btn btn-outline small" data-action="flip">${icon('refresh')} Çevir</button><button class="btn btn-outline small" data-action="hint">${icon('info')} İpucu</button><button class="btn btn-outline small" data-action="sound" data-text="${attr(t.de)}">${icon('sound')} Dinle</button><button class="btn btn-outline small" data-action="next">Sonraki ${icon('right')}</button></div><div class="status-prompt">Kartın ne kadarını öğrendin?</div><div class="response-actions"><button class="btn btn-outline" data-action="rate" data-value="no">${icon('refresh')} Tekrar Çalışmalıyım</button><button class="btn btn-primary" data-action="rate" data-value="yes">${icon('check')} Öğrendim</button></div><div class="status-prompt">Klavye: ← → kart değiştir, boşluk kartı çevir.</div>`);
}
function getDistractors(t){let other=shuffle(allTerms().filter(x=>x.id!==t.id && norm(x.tr)!==norm(t.tr)));return shuffle([t.tr,...unique(other.map(x=>x.tr)).slice(0,3)]);}
function quizView(){const t=getTerm(session.ids[session.idx]);if(!t)return missing();if(!session.options||session.optionAt!==session.idx){session.options=getDistractors(t);session.optionAt=session.idx;}
return studyShell('Çoktan Seçmeli Test',`<div class="row-flex" style="margin-top:18px"><span class="muted tiny">Soru ${session.idx+1} / ${session.ids.length}</span><span class="pill blue">${session.answers.filter(a=>a.correct).length} doğru</span></div>${progressBar()}<div class="surface quiz-question"><span class="qmeta">ALMANCA → TÜRKÇE</span><h2>${E(t.de)} ne demektir?</h2><div class="options">${session.options.map((answer,i)=>`<button class="option ${session.selected===null?'':norm(answer)===norm(t.tr)?'correct':session.selected===answer?'incorrect':''}" data-action="quiz-answer" data-value="${attr(answer)}" ${session.selected!==null?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${E(answer)}</button>`).join('')}</div>${session.selected!==null?`<div class="feedback ${norm(session.selected)===norm(t.tr)?'correct':'incorrect'}">${norm(session.selected)===norm(t.tr)?'Doğru cevap!':'Doğru cevap: '+E(t.tr)}</div><div class="row-flex" style="margin-top:19px"><p class="muted tiny">${E(t.examples[0]?.de||'')}</p><button class="btn btn-primary" data-action="quiz-next">${session.idx===session.ids.length-1?'Sonuçları Gör':'Sonraki Soru'} ${icon('arrow')}</button></div>`:''}</div>`);
}
function writeView(){const t=getTerm(session.ids[session.idx]);if(!t)return missing();const answered=session.written;
return studyShell('Yazma Alıştırması',`<div class="row-flex" style="margin-top:18px"><span class="muted tiny">Soru ${session.idx+1} / ${session.ids.length}</span><label class="tiny"><input type="checkbox" id="ignoreArticle" ${session.ignoreArticle?'checked':''} data-action="ignore-article"> Artikeli es geç</label></div>${progressBar()}<form data-form="write-answer" class="surface quiz-question"><div class="qmeta">TÜRKÇE → ALMANCA</div><h2>${E(t.tr)}</h2><p class="muted tiny">Almanca karşılığını yazın:</p><input class="write-answer" id="writeInput" name="answer" autocomplete="off" placeholder="Örn: der Vertrag" ${answered?'disabled':''} aria-label="Almanca cevap" required>${answered?`<div class="feedback ${session.lastCorrect?'correct':'incorrect'}">${session.lastCorrect?'Doğru!':'Doğru cevap: '+E(t.de)}</div><button type="button" class="btn btn-primary" data-action="write-next">${session.idx===session.ids.length-1?'Sonuçları Gör':'Sonraki Kelime'} ${icon('arrow')}</button>`:`<button class="btn btn-primary" type="submit">Cevabı Kontrol Et ${icon('check')}</button>`}</form>`);
}
function matchView(){const count=session.matched.length,total=session.matchIds.length;return studyShell('Eşleştirme Oyunu',`<div class="row-flex" style="margin:20px 0"><span class="muted tiny">${count} / ${total} eşleştirme</span><span class="pill blue">${session.wrongClicks} yanlış deneme</span></div><div class="progress-track"><div style="width:${Math.round(count/total*100)}%"></div></div><div class="match-grid"><div class="match-col">${session.left.map(id=>`<button data-action="match-left" data-id="${attr(id)}" class="match-item ${session.matched.includes(id)?'matched':session.selectedLeft===id?'selected':''}" ${session.matched.includes(id)?'disabled':''}>${E(getTerm(id)?.de||'')}</button>`).join('')}</div><div class="match-col">${session.right.map(id=>`<button data-action="match-right" data-id="${attr(id)}" class="match-item ${session.matched.includes(id)?'matched':session.selectedRight===id?'selected':''}" ${session.matched.includes(id)?'disabled':''}>${E(getTerm(id)?.tr||'')}</button>`).join('')}</div></div><p class="muted tiny" style="text-align:center;margin-top:22px">Soldan bir Almanca kelime ve sağdan Türkçe karşılığını seçin.</p>`);}
function resultView(){const answers=session.answers||[];const total=answers.length||session.matchIds?.length||session.ids.length;const correct=answers.length?answers.filter(a=>a.correct).length:Math.max(0,total-session.wrongClicks);const rate=Math.round(correct/Math.max(1,total)*100);
const wrong=answers.filter(a=>!a.correct).map(a=>getTerm(a.id)).filter(Boolean);
return studyShell('Çalışma Sonucu',`<div class="surface quiz-question" style="text-align:center;margin-top:26px"><span class="kicker">ÇALIŞMA TAMAMLANDI</span><h2 style="font-size:50px;margin-top:17px">${rate}%</h2><p class="muted">${correct} doğru · ${total-correct} yanlış · ${total} soru</p><div class="filterbar" style="justify-content:center;margin-top:23px"><button class="btn btn-primary" data-action="restart">${icon('refresh')} Tekrar Çalış</button><a href="#/study" class="btn btn-outline">Diğer Listeler</a>${wrong.length?`<button class="btn btn-gold" data-action="retry-wrong">Yanlışları Tekrar Et (${wrong.length})</button>`:''}</div></div>${wrong.length?`<div class="surface card" style="margin-top:20px"><h3>Tekrar edilecek kelimeler</h3>${wrong.map(t=>`<div class="progress-item"><a class="link" href="#/word/${attr(t.id)}">${E(t.de)}</a><span class="muted tiny">${E(t.tr)}</span></div>`).join('')}</div>`:''}`);
}
function playView(mode,listId){if(!['flash','quiz','write','match'].includes(mode))return missing();if(!session||session.mode!==mode||session.listId!==listId){session=null;const ids=listId==='all'?allTerms().map(t=>t.id):listTerms(listId).map(t=>t.id);if(!ids.length)return missing();const arr=shuffle(ids);session={mode,listId,ids:(mode==='quiz'||mode==='write')?arr.slice(0,10):arr,idx:0,flipped:false,hint:false,reverse:false,selected:null,answers:[],written:false,wrongClicks:0,start:Date.now(),done:false};if(mode==='match')setupMatches();}
if(session.done)return resultView();return {flash:flashView,quiz:quizView,write:writeView,match:matchView}[mode]();}
function dashboard(){const total=allTerms().length;const progress=Object.entries(state.progress).filter(([id,p])=>!!getTerm(id));const learned=progress.filter(([,p])=>p.status==='learned').length;const due=progress.filter(([,p])=>p.next<=today() && p.status!=='learned').length;const doneToday=progress.filter(([,p])=>p.last===today()).length;
return `${heading('Kişisel Çalışma Alanım','Favorilerinizi, kelime tekrarlarınızı ve kişisel listelerinizi burada yönetin.',[{label:'Panelim'}])}<div class="container page-content"><div class="note" style="margin-bottom:24px">${icon('info')} Bu sürümde hesap girişi yoktur. Çalışma verileri yalnızca bu tarayıcıda saklanır; başka cihazlara otomatik aktarılmaz.</div><div class="stat-grid">${[['Öğrenilen kelimeler',learned],['Tekrar bekleyenler',due],['Favorilerim',state.favorites.length],['Bugün çalışılan',doneToday]].map(([l,v])=>`<div class="surface stat-card"><div class="number">${v}</div><div class="desc">${l}</div></div>`).join('')}</div><div class="panel-layout"><div class="panel-stack"><div class="surface card"><div class="row-flex"><h3>Favori kelimelerim</h3><a href="#/dictionary" class="link tiny">Sözlükte ara</a></div>${state.favorites.length?state.favorites.map(id=>getTerm(id)).filter(Boolean).slice(0,12).map(t=>`<div class="progress-item"><a class="link" href="#/word/${attr(t.id)}">${E(t.de)}</a><span class="muted tiny">${E(t.tr)}</span></div>`).join(''):'<p class="muted tiny">Henüz favori eklemediniz. Sözlükten kalp simgesine basarak başlayın.</p>'}</div><div class="surface card"><div class="row-flex"><h3>Kişisel kelime listelerim</h3><button class="btn btn-primary small" data-action="new-list">${icon('plus')} Yeni Liste</button></div>${state.myLists.length?state.myLists.map(l=>`<div class="progress-item"><a href="#/list/${attr(l.id)}" class="link">${E(l.name)}</a><span class="muted tiny">${l.ids.length} kelime</span><button class="btn btn-danger small" data-action="delete-list" data-id="${attr(l.id)}">Sil</button></div>`).join(''):'<p class="muted tiny">Kendi çalışma listenizi oluşturabilirsiniz.</p>'}</div></div><div class="panel-stack"><div class="surface card"><h3>Günlük hedefim</h3><p class="muted tiny">Bugün ${doneToday} kelime çalışıldı.</p><div class="progress-track"><div style="width:${Math.min(100,doneToday/state.dailyGoal*100)}%"></div></div><label class="tiny muted" for="dailyGoal">Günlük hedef (kelime)</label><div class="filterbar"><input type="number" id="dailyGoal" class="field" min="1" max="500" value="${state.dailyGoal}" style="width:100px"><button class="btn btn-outline" data-action="save-goal">Kaydet</button></div></div><div class="surface card"><h3>Son çalışma oturumları</h3>${state.sessions.length?state.sessions.slice(0,8).map(s=>`<div class="progress-item"><span>${E(modeNames[s.mode]||s.mode)}</span><span class="muted tiny">${s.correct}/${s.total} · ${E(s.date)}</span></div>`).join(''):'<p class="muted tiny">Tamamlanan testler burada görünecek.</p>'}<button data-action="export-progress" class="btn btn-light small" style="margin-top:12px">${icon('download')} Verilerimi İndir</button></div><div class="surface card"><h3>Yeni bir çalışma başlatın</h3><p class="muted tiny">Tüm sözlükten rastgele kelimeler çözün.</p><button class="btn btn-primary" data-action="start-study" data-list="all" data-mode="flash">Kartları Aç ${icon('arrow')}</button></div></div></div></div>`;}
function about(){return `${heading('LexHukuk Hakkında','Almanca hukuk dilini daha anlaşılır hâle getirmek için tasarlandı.',[{label:'Hakkında'}])}<div class="container section"><div class="section-top"><div><div class="kicker">MİSYONUMUZ</div><h2>Dilin ötesinde, hukuki bağlamı kavramak.</h2><p>Almanca öğrenen hukuk öğrencileri için kelimeleri yalnızca karşılıklarıyla değil, kullanıldıkları cümlelerle ve hukuk alanlarıyla birlikte sunuyoruz.</p></div></div><div class="about-grid"><div class="surface card"><div class="category-icon">${icon('search','lg')}</div><h3 style="margin-top:20px">Bağlamlı Sözlük</h3><p class="muted tiny">Almanca tanım, Türkçe açıklama ve iki dilli örnek cümleler.</p></div><div class="surface card"><div class="category-icon">${icon('book','lg')}</div><h3 style="margin-top:20px">Tematik Listeler</h3><p class="muted tiny">17 hukuk alanı ve seviyelere ayrılmış genel Almanca.</p></div><div class="surface card"><div class="category-icon">${icon('card','lg')}</div><h3 style="margin-top:20px">Aktif Tekrar</h3><p class="muted tiny">Flashcard, test, yazma ve eşleştirme egzersizleri.</p></div></div><div class="surface card" style="margin-top:27px"><h3>Önemli açıklama</h3><p>Bu sürüm GitHub Pages için hazırlanmış tarayıcı tabanlı bir prototiptir. Kullanıcı hesabı, güvenli sunucu veritabanı ve hesaplar arası senkronizasyon barındırmaz. Favoriler ve çalışma verileri yalnızca kullanılan cihazdaki tarayıcıda saklanır.</p><p>Alman ve Türk hukukundaki terimler bazen aynı adı taşısa da hukuki içerikleri farklı olabilir. Her örnek tanım akademik kaynaklarla doğrulanmalıdır. Resmî Alman mevzuatı için <a class="link" href="https://www.gesetze-im-internet.de/" target="_blank" rel="noopener noreferrer">gesetze-im-internet.de</a> incelenebilir.</p></div></div>`;}
function editor(){return `${heading('Yerel Kelime Editörü','Sözlük verilerini bu cihazda düzenleyin, CSV içe aktarın ve yedek oluşturun.',[{label:'Yerel Editör'}])}<div class="container page-content"><div class="note" style="margin-bottom:23px">${icon('info')} Bu ekran <strong>güvenli sunucu yönetim paneli değildir</strong>. Her ziyaretçi kendi tarayıcısındaki kopyayı değiştirebilir; değişiklikler GitHub deposuna veya diğer kullanıcılara aktarılmaz.</div><div class="panel-layout"><section class="surface card"><h3>Yeni terim ekle / yerel terimi düzenle</h3><form data-form="term" class="edit-controls"><label>Almanca terim (artikel dâhil)<input name="de" required class="input" placeholder="die Verordnung"></label><label>Türkçe karşılık<input name="tr" required class="input" placeholder="Düzenleme"></label><label>Hukuk alanı<select name="category" class="select">${db.categories.map(c=>`<option value="${attr(c.id)}">${E(c.tr)}</option>`).join('')}</select></label><label>Seviye<select name="level" class="select">${['A1','A2','B1','B2','C1'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Almanca tanım<input name="definitionDE" required class="input" placeholder="Eine ..."></label><label>Türkçe açıklama<input name="definitionTR" required class="input" placeholder="... anlamına gelir."></label><label>Örnek 1 · Almanca<input name="de1" required class="input" placeholder="Der Vertrag ist wirksam."></label><label>Örnek 1 · Türkçe<input name="tr1" required class="input" placeholder="Sözleşme geçerlidir."></label><label>Örnek 2 · Almanca<input name="de2" required class="input"></label><label>Örnek 2 · Türkçe<input name="tr2" required class="input"></label><button class="btn btn-primary" type="submit">${icon('plus')} Terimi Kaydet</button></form></section><section class="panel-stack"><div class="surface card"><h3>Toplu içe / dışa aktar</h3><p class="muted tiny">CSV sütunları: de, tr, category, level, definitionDE, definitionTR, de1, tr1, de2, tr2</p><div class="upload-zone"><label for="csvImport" class="tiny muted">CSV dosyasını seçin</label><input type="file" id="csvImport" accept=".csv,text/csv"></div><div class="filterbar" style="margin-top:13px"><button data-action="download-csv" class="btn btn-outline">${icon('download')} CSV Şablonu</button><button data-action="export-terms" class="btn btn-outline">${icon('download')} Terimleri JSON İndir</button></div></div><div class="surface card"><h3>Bu tarayıcıda eklenen kelimeler</h3><p class="muted tiny">${state.custom.length} düzenlenmiş / eklenmiş terim.</p>${state.custom.length?state.custom.slice(0,25).map(t=>`<div class="progress-item"><a class="link" href="#/word/${attr(t.id)}">${E(t.de)}</a><button class="btn btn-danger small" data-action="remove-custom" data-id="${attr(t.id)}">Sil</button></div>`).join(''):'<p class="tiny muted">Şu anda yerel ekleme yok.</p>'}</div><div class="surface card"><h3>Hata bildirimleri</h3>${state.reports.length?state.reports.slice(-8).reverse().map(r=>`<div class="progress-item"><span>${E(r.term)}<br><span class="muted tiny">${E(r.message)}</span></span></div>`).join(''):'<p class="muted tiny">Bu tarayıcıdan henüz hata bildirimi yapılmadı.</p>'}</div></section></div></div>`;}
function parseHash(){const str=(location.hash||'#/').slice(1);const path=str.split('?')[0];return path.replace(/^\/+|\/+$/g,'').split('/').filter(Boolean).map(decodeURIComponent);}
function render(){mobileOpen=false;let paths=parseHash();const route=paths[0]||'home';let content,active=route;switch(route){case 'home':content=home();break;case 'dictionary':content=dictionaryView();break;case 'word':content=wordView(paths[1]);active='dictionary';break;case 'lists':content=listsView();break;case 'list':content=listView(paths[1]);active='lists';break;case 'study':content=studyLanding();break;case 'play':content=playView(paths[1],paths[2]);active='study';break;case 'dashboard':content=dashboard();break;case 'about':content=about();break;case 'editor':content=editor();active='dashboard';break;default:content=missing();active='home';}
document.getElementById('app').innerHTML=wrap(content,active);document.title=`${route==='word'?(getTerm(paths[1])?.de+' | '):''}LexHukuk | Almanca–Türkçe Hukuk Sözlüğü`;
}
function updateSuggestion(inp){const container=document.getElementById(inp.id+'-suggestions');if(!container)return;const query=inp.value.trim();const data=query?searchResults(query).slice(0,6):[];container.hidden=data.length===0;container.innerHTML=data.map(t=>`<button type="button" data-action="open-word" data-id="${attr(t.id)}"><span><strong>${E(t.de)}</strong> <small>· ${E(cat(t.category).tr)}</small></span><small>${E(t.tr)} ${icon('right','sm')}</small></button>`).join('');}
function gotoSearch(q){dictionary.query=(q||'').trim();dictionary.category='all';dictionary.level='all';const h='#/dictionary'+(dictionary.query?'?q='+encodeURIComponent(dictionary.query):'');if(location.hash===h)render();else location.hash=h;}
function downloadFile(name,data,mime){const blob=new Blob([data],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function speech(text){if(!('speechSynthesis' in window)){toast('Bu tarayıcı seslendirmeyi desteklemiyor.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=.84;speechSynthesis.speak(u);}
function complete(){if(session.done)return;session.done=true;const correct=session.answers.filter(a=>a.correct).length;const total=session.mode==='match'?session.matchIds.length:session.answers.length;saveSession(session.mode,session.mode==='match'?total:correct,total);render();}
function nextCard(){session.idx=(session.idx+1)%session.ids.length;session.flipped=false;session.hint=false;render();}
function setFavorite(id){const idx=state.favorites.indexOf(id);if(idx>=0)state.favorites.splice(idx,1);else state.favorites.push(id);persist();render();toast(idx>=0?'Favorilerden çıkarıldı.':'Favorilere eklendi.');}
function addToList(id){if(!state.myLists.length){const name=prompt('Yeni kelime listesi adı:');if(!name||!name.trim())return;state.myLists.push({id:'mine-'+Date.now(),name:name.trim(),ids:[id]});toast('Yeni listene eklendi.');}else{const options=state.myLists.map((l,i)=>`${i+1}. ${l.name}`).join('\n');const choice=prompt(`Kelimeyi hangi listeye eklemek istiyorsun?\n${options}\nYeni liste için 0 yazın.`);if(choice===null)return;const n=Number(choice);if(n===0){const name=prompt('Liste adı:');if(!name?.trim())return;state.myLists.push({id:'mine-'+Date.now(),name:name.trim(),ids:[id]});}else if(n>0&&n<=state.myLists.length){const li=state.myLists[n-1];li.ids=unique([...li.ids,id]);}else{toast('Geçersiz liste numarası.');return;}}persist();toast('Kelime listene eklendi.');}
function checkMatch(){if(!session.selectedLeft||!session.selectedRight)return;if(session.selectedLeft===session.selectedRight){session.matched.push(session.selectedLeft);markProgress(session.selectedLeft,true);session.selectedLeft=null;session.selectedRight=null;if(session.matched.length===session.matchIds.length){session.answers=session.matchIds.map(id=>({id,correct:true}));complete();return;}}else{session.wrongClicks++;session.selectedLeft=null;session.selectedRight=null;toast('Eşleşmedi, tekrar dene.');}render();}
function slug(text){return norm(text).replace(/\s+/g,'-').replace(/[^a-z0-9-]/g,'')||'term';}
function parseCsv(text){const out=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){field+='"';i++;}else if(ch==='"'){quoted=false;}else field+=ch;}else if(ch==='"'){quoted=true;}else if(ch===','){row.push(field);field='';}else if(ch==='\n'){row.push(field);out.push(row);row=[];field='';}else if(ch!=='\r'){field+=ch;}}row.push(field);if(row.some(x=>x))out.push(row);return out;}
function csvImport(file){if(!file)return;if(file.size>2_000_000){toast('CSV dosyası 2 MB altında olmalıdır.');return;}const reader=new FileReader();reader.onload=()=>{try{const rows=parseCsv(String(reader.result||''));const headings=rows.shift().map(x=>x.trim().replace(/^\uFEFF/,''));let count=0;for(const cells of rows){const o=Object.fromEntries(headings.map((h,i)=>[h,(cells[i]||'').trim()]));if(!o.de||!o.tr||!o.de1||!o.tr1||!o.de2||!o.tr2)continue;const id=slug(o.de);const art=/^(der|die|das)\s/.exec(o.de)?.[1]||'';const term={id,de:o.de,tr:o.tr,word:o.de.replace(/^(der|die|das)\s/,''),article:art,plural:null,type:art?'isim':'fiil / diğer',category:db.categories.some(c=>c.id===o.category)?o.category:'general',level:['A1','A2','B1','B2','C1'].includes(o.level)?o.level:'B1',definitionDE:o.definitionDE||'',definitionTR:o.definitionTR||'',examples:[{de:o.de1,tr:o.tr1},{de:o.de2,tr:o.tr2}],legal:o.category!=='general'};state.custom=state.custom.filter(t=>t.id!==id);state.custom.push(term);count++;}persist();render();toast(`${count} kelime bu tarayıcıya aktarıldı.`);}catch(e){toast('CSV okunamadı. Sütunları kontrol edin.');}};reader.readAsText(file,'utf-8');}
document.addEventListener('submit',evt=>{const form=evt.target;if(!(form instanceof HTMLFormElement))return;const kind=form.dataset.form;if(!kind)return;evt.preventDefault();if(kind==='search'){gotoSearch(new FormData(form).get('query'));}
if(kind==='write-answer'&&session&&session.mode==='write'){const t=getTerm(session.ids[session.idx]);const typed=String(new FormData(form).get('answer')||'').trim();if(!typed)return;const correct=norm(typed)===norm(t.de)||(session.ignoreArticle&&norm(typed.replace(/^(der|die|das)\s/,''))===norm(t.word));session.lastCorrect=correct;session.written=true;session.answers.push({id:t.id,correct});markProgress(t.id,correct);render();}
if(kind==='term'){const values=Object.fromEntries(new FormData(form));const id=slug(values.de);const article=/^(der|die|das)\s/.exec(values.de)?.[1]||'';const t={id,de:values.de.trim(),tr:values.tr.trim(),word:values.de.trim().replace(/^(der|die|das)\s/,''),article,plural:null,type:article?'isim':'diğer',category:values.category,level:values.level,definitionDE:values.definitionDE.trim(),definitionTR:values.definitionTR.trim(),examples:[{de:values.de1.trim(),tr:values.tr1.trim()},{de:values.de2.trim(),tr:values.tr2.trim()}],legal:values.category!=='general'};state.custom=state.custom.filter(x=>x.id!==id);state.custom.push(t);state.hidden=state.hidden.filter(x=>x!==id);persist();location.hash=`#/word/${encodeURIComponent(id)}`;toast('Terim yerel olarak kaydedildi.');}
});
document.addEventListener('input',evt=>{const el=evt.target;if(el.matches('[data-search]'))updateSuggestion(el);if(el.matches('[data-dictionary-query]')){dictionary.query=el.value;try{history.replaceState(null,'',location.pathname+location.search+'#/dictionary'+(dictionary.query?'?q='+encodeURIComponent(dictionary.query):''));}catch{}const position=el.selectionStart;render();const newEl=document.getElementById('dictionaryInput');newEl?.focus();newEl?.setSelectionRange(position,position);}if(el.matches('[data-list-search]')){listFilter.query=el.value;const pos=el.selectionStart;render();const newEl=document.getElementById('listSearch');newEl?.focus();newEl?.setSelectionRange(pos,pos);}});
document.addEventListener('change',evt=>{const el=evt.target;if(el.matches('[data-filter]')){dictionary[el.dataset.filter]=el.value;render();}if(el.id==='csvImport')csvImport(el.files?.[0]);if(el.id==='ignoreArticle'&&session){session.ignoreArticle=el.checked;}});
document.addEventListener('click',evt=>{const btn=evt.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,id=btn.dataset.id,mode=btn.dataset.mode;
if(!['sound','favorite'].includes(action))evt.preventDefault();
switch(action){case 'menu':mobileOpen=!mobileOpen;document.querySelector('.nav')?.classList.toggle('open',mobileOpen);break;
case 'search-word':gotoSearch(btn.dataset.value);break;case 'open-word':location.hash='#/word/'+encodeURIComponent(id);break;
case 'favorite':setFavorite(id);break;case 'sound':speech(btn.dataset.text||'');break;case 'reset-dictionary':dictionary={query:'',category:'all',level:'all',sort:'az',type:'all'};location.hash='#/dictionary';render();break;
case 'list-filter':listFilter.kind=id;render();break;
case 'share':{const url=location.href.split('#')[0]+'#/word/'+encodeURIComponent(id);if(navigator.share){navigator.share({url}).catch(()=>{});}else if(navigator.clipboard){navigator.clipboard.writeText(url).then(()=>toast('Bağlantı kopyalandı.')).catch(()=>prompt('Bağlantıyı kopyalayın:',url));}else prompt('Bağlantıyı kopyalayın:',url);break;}
case 'pick-list':addToList(id);break;case 'report':{const message=prompt('Bu kelimedeki hatayı kısaca açıklayın:');if(!message?.trim())break;state.reports.push({id,term:getTerm(id)?.de||id,message:message.trim(),date:today()});persist();toast('Bildirim bu tarayıcıya kaydedildi.');break;}
case 'study-single':makeSession('flash','single',[id]);break;case 'start-study':makeSession(mode,btn.dataset.list);break;
case 'previous':if(session){session.idx=Math.max(0,session.idx-1);session.flipped=false;session.hint=false;render();}break;
case 'next':if(session)nextCard();break;
case 'flip':if(session){session.flipped=!session.flipped;render();}break;
case 'hint':if(session){session.hint=!session.hint;render();}break;
case 'direction':if(session){session.reverse=!session.reverse;session.flipped=false;render();}break;
case 'rate':if(session){markProgress(session.ids[session.idx],btn.dataset.value==='yes');nextCard();toast(btn.dataset.value==='yes'?'Öğrenme ilerlemen kaydedildi.':'Kelime tekrar planına eklendi.');}break;
case 'restart':if(session)makeSession(session.mode,session.listId);break;
case 'quiz-answer':if(session&&session.selected===null){session.selected=btn.dataset.value;const t=getTerm(session.ids[session.idx]);const correct=norm(session.selected)===norm(t.tr);session.answers.push({id:t.id,correct});markProgress(t.id,correct);render();}break;
case 'quiz-next':if(session){if(session.idx>=session.ids.length-1){complete();}else{session.idx++;session.selected=null;render();}}break;
case 'write-next':if(session){if(session.idx>=session.ids.length-1){complete();}else{session.idx++;session.written=false;session.lastCorrect=false;render();document.getElementById('writeInput')?.focus();}}break;
case 'match-left':if(session){session.selectedLeft=id;checkMatch();if(!session.selectedRight)render();}break;
case 'match-right':if(session){session.selectedRight=id;checkMatch();if(!session.selectedLeft)render();}break;
case 'retry-wrong':{const wrong=session.answers.filter(a=>!a.correct).map(a=>a.id);makeSession('flash','single',wrong);break;}
case 'new-list':{const name=prompt('Yeni listenin adı nedir?');if(!name?.trim())break;state.myLists.push({id:'mine-'+Date.now(),name:name.trim().slice(0,60),ids:[]});persist();render();toast('Liste oluşturuldu.');break;}
case 'delete-list':{if(!confirm('Bu kişisel liste silinsin mi?'))break;state.myLists=state.myLists.filter(x=>x.id!==id);persist();render();break;}
case 'save-goal':{const n=Number(document.getElementById('dailyGoal')?.value);if(n<1||n>500||!Number.isFinite(n)){toast('1–500 arasında bir hedef girin.');break;}state.dailyGoal=n;persist();render();toast('Hedef güncellendi.');break;}
case 'export-progress':downloadFile('lexhukuk-ilerleme.json',JSON.stringify({favorites:state.favorites,progress:state.progress,myLists:state.myLists,sessions:state.sessions},null,2),'application/json');break;
case 'export-terms':downloadFile('lexhukuk-kelimeler.json',JSON.stringify(allTerms(),null,2),'application/json');break;
case 'download-csv':{const row=['de','tr','category','level','definitionDE','definitionTR','de1','tr1','de2','tr2'];downloadFile('lexhukuk-ornek.csv',row.join(',')+'\n"die Klage","dava","zivilprozess","B1","Ein Antrag auf Rechtsschutz.","Mahkemeden hukuki koruma talebi.","Die Klägerin erhebt Klage.","Davacı dava açar.","Das Gericht weist die Klage ab.","Mahkeme davayı reddeder."\n','text/csv;charset=utf-8');break;}
case 'remove-custom':{if(!confirm('Bu yerel içerik silinsin mi?'))break;state.custom=state.custom.filter(x=>x.id!==id);persist();render();break;}
}
});
document.addEventListener('keydown',evt=>{if(!session||session.mode!=='flash'||!location.hash.includes('/play/flash'))return;if(evt.target.closest('input,textarea,select,button'))return;if(evt.key===' '){evt.preventDefault();session.flipped=!session.flipped;render();}if(evt.key==='ArrowRight'){evt.preventDefault();nextCard();}if(evt.key==='ArrowLeft'){evt.preventDefault();session.idx=Math.max(0,session.idx-1);session.flipped=false;render();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
render();
})();
